// ─── UTILS ────────────────────────────────────────────────────────────────────
function Toast({msg,type}){if(!msg)return null;return <div className={`toast ${type}`}>{msg}</div>;}
function useToast(){
  const [t,setT]=useState(null);
  const show=useCallback((msg,type="success")=>{setT({msg,type});setTimeout(()=>setT(null),3500);},[]);
  return {toast:t,show};
}
function validate(rules,data){
  const e={};
  for(const[f,l] of Object.entries(rules)) if(!data[f]||String(data[f]).trim()==="") e[f]=`${l} obligatoire`;
  return e;
}
function FieldErr({errs,field}){return errs[field]?<div className="field-error">⚠ {errs[field]}</div>:null;}
function Modal({title,onClose,children}){
  return(
    <div className="modal-overlay" onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div className="modal">
        <div className="modal-header"><div className="modal-title">{title}</div><button className="modal-close" onClick={onClose}>×</button></div>
        <div className="modal-body">{children}</div>
      </div>
    </div>
  );
}
function ConfirmModal({title,text,onConfirm,onCancel}){
  return(
    <div className="modal-overlay">
      <div className="confirm-modal">
        <div className="modal-title">{title}</div>
        <div className="confirm-text">{text}</div>
        <div className="flex gap-2"><button className="btn btn-danger" onClick={onConfirm}>Confirmer</button><button className="btn btn-secondary" onClick={onCancel}>Annuler</button></div>
      </div>
    </div>
  );
}
function IntensityBadge({level}){
  const m={Haute:"#e50000",Moyenne:"#ff6400",Faible:"#39d353"};
  return <span className="intensity"><span className="intensity-dot" style={{background:m[level]||"#666"}}/><span className="text-sm text-muted">{level}</span></span>;
}
function LevelBadge({level}){
  if(!level)return null;
  const c={Debutant:"badge-green",Intermediaire:"badge-orange",Avance:"badge-blue",Competiteur:"badge-red"};
  return <span className={`badge ${c[level]||"badge-dark"}`}>{level}</span>;
}

// Avatar universel — photo ou lettre
function Avatar({user,size="sm",className=""}){
  const cls = size==="lg" ? "avatar-lg" : "avatar";
  return(
    <div className={`${cls} ${className}`}>
      {user?.avatar_url
        ? <img src={user.avatar_url} alt={user.name} onError={e=>{e.target.style.display="none";}}/>
        : <span>{(user?.name||"?")[0].toUpperCase()}</span>
      }
    </div>
  );
}

// Upload avatar avec preview
function AvatarUpload({user,onUpload}){
  const inputRef=useRef(null);
  const [uploading,setUploading]=useState(false);
  const handle=async(e)=>{
    const file=e.target.files?.[0];
    if(!file)return;
    if(file.size>2*1024*1024){alert("Fichier trop lourd (max 2MB)");return;}
    setUploading(true);
    const url=await uploadAvatar(file,user.id);
    if(url){
      await supabase.from("profiles").update({avatar_url:url}).eq("id",user.id);
      onUpload(url);
    }
    setUploading(false);
  };
  return(
    <div className="avatar-upload" onClick={()=>inputRef.current?.click()}>
      <div className="avatar-lg">
        {user?.avatar_url
          ? <img src={user.avatar_url} alt={user.name}/>
          : <span>{(user?.name||"?")[0].toUpperCase()}</span>
        }
      </div>
      <div className="avatar-upload-overlay">{uploading?"...":"📷 Changer"}</div>
      <input ref={inputRef} type="file" accept="image/*" style={{display:"none"}} onChange={handle}/>
    </div>
  );
}

function AnnounceBanner({announces}){
  const active=(announces||[]).filter(a=>a.active);
  if(!active.length)return null;
  const a=active[0];
  const bg={info:"rgba(0,191,255,.12)",warning:"rgba(255,100,0,.12)",urgent:"rgba(204,0,0,.18)"};
  const border={info:"#00bfff",warning:"#ff6400",urgent:"var(--red)"};
  const icon={info:"ℹ️",warning:"⚠️",urgent:"🚨"};
  return(
    <div className="announce-banner" style={{background:bg[a.type]||bg.info,borderBottom:`1px solid ${border[a.type]||border.info}`}}>
      <span>{icon[a.type]||"ℹ️"}</span>
      <span style={{fontWeight:700}}>{a.title}</span>
      {a.content&&<span style={{color:"var(--text2)",fontWeight:400}}>— {a.content}</span>}
    </div>
  );
}

function SessionCard({s,canEdit,onEdit}){
  const coaches=[s.coach_name,...(s.extra_coaches||[])].filter(Boolean);
  const unique=[...new Set(coaches)];
  const types=Array.isArray(s.types)&&s.types.length>0 ? s.types : s.type ? [s.type] : [];
  return(
    <div className="card">
      <div className="card-header">
        <div>
          <div style={{fontFamily:"var(--font-display)",fontSize:"1rem",fontWeight:900,color:"var(--text)",letterSpacing:".04em"}}>
            {getDayName(s.date)} {formatDate(s.date)}{s.time_label?` — ${s.time_label}`:""}
          </div>
          <div className="card-title" style={{marginTop:4}}>{s.focus}</div>
          <div className="card-meta">{s.duration} min{s.group_name?` — ${s.group_name}`:""}</div>
          <div className="flex gap-2 items-center" style={{marginTop:6,flexWrap:"wrap"}}>
            {unique.map((c,i)=><span key={i} className="coach-tag">🥋 {c}</span>)}
          </div>
        </div>
        <div className="flex gap-2 items-center" style={{flexWrap:"wrap",flexShrink:0}}>
          {types.map((t,i)=><span key={i} className="badge badge-red">{t}</span>)}
          {isMardi(s.date)&&<span className="badge badge-compet">Compet.</span>}
          {canEdit&&<button className="btn btn-sm btn-edit" onClick={()=>onEdit(s)}>Modifier</button>}
        </div>
      </div>
      {s.notes&&<div className="text-sm text-muted" style={{marginBottom:7}}>{s.notes}</div>}
      <div className="ex-list">{(s.exercises||[]).map((e,i)=><span key={i} className="ex-tag">{e}</span>)}</div>
    </div>
  );
}

